import pytest
from typing import Any, Type
from scrapy.crawler import Crawler
from scrapy.utils.misc import build_from_crawler
from scrapy.utils.test import get_crawler


class TestBuildFromCrawler:
    def setup_method(self) -> None:
        self.crawler = get_crawler()

    def test_build_from_crawler_with_from_crawler_method(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler: Crawler, /, *args: Any, **kwargs: Any) -> Any:
                return cls(*args, **kwargs)

        instance = build_from_crawler(MyClass, self.crawler, arg1=1, arg2=2)
        assert isinstance(instance, MyClass)
        assert instance.arg1 == 1
        assert instance.arg2 == 2

    def test_build_from_crawler_without_from_crawler_method(self) -> None:
        class MyClass:
            def __init__(self, *args: Any, **kwargs: Any) -> None:
                self.args = args
                self.kwargs = kwargs

        instance = build_from_crawler(MyClass, self.crawler, arg1=1, arg2=2)
        assert isinstance(instance, MyClass)
        assert instance.args == (1, 2)
        assert instance.kwargs == {}

    def test_build_from_crawler_with_none_return(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler: Crawler, /, *args: Any, **kwargs: Any) -> Any:
                return None

        with pytest.raises(TypeError):
            build_from_crawler(MyClass, self.crawler)

    def test_build_from_crawler_with_invalid_class(self) -> None:
        with pytest.raises(TypeError):
            build_from_crawler(123, self.crawler)

    def test_build_from_crawler_with_invalid_crawler(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler: Crawler, /, *args: Any, **kwargs: Any) -> Any:
                return cls(*args, **kwargs)

        with pytest.raises(AttributeError):
            build_from_crawler(MyClass, None)

    def test_build_from_crawler_with_mixed_args_and_kwargs(self) -> None:
        class MyClass:
            def __init__(self, arg1: Any, arg2: Any, kwarg1: Any, kwarg2: Any) -> None:
                self.arg1 = arg1
                self.arg2 = arg2
                self.kwarg1 = kwarg1
                self.kwarg2 = kwarg2

        instance = build_from_crawler(MyClass, self.crawler, 1, 2, kwarg1=3, kwarg2=4)
        assert isinstance(instance, MyClass)
        assert instance.arg1 == 1
        assert instance.arg2 == 2
        assert instance.kwarg1 == 3
        assert instance.kwarg2 == 4

    def test_build_from_crawler_with_no_args_no_kwargs(self) -> None:
        class MyClass:
            def __init__(self) -> None:
                pass

        instance = build_from_crawler(MyClass, self.crawler)
        assert isinstance(instance, MyClass)

    def test_build_from_crawler_with_only_kwargs(self) -> None:
        class MyClass:
            def __init__(self, kwarg1: Any, kwarg2: Any) -> None:
                self.kwarg1 = kwarg1
                self.kwarg2 = kwarg2

        instance = build_from_crawler(MyClass, self.crawler, kwarg1=1, kwarg2=2)
        assert isinstance(instance, MyClass)
        assert instance.kwarg1 == 1
        assert instance.kwarg2 == 2

